const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < n - 1; i++) {
  const u = tok[1 + 2 * i], v = tok[2 + 2 * i];
  adj[u].push(v);
  adj[v].push(u);
}
const parent = new Array(n + 1).fill(0);
const seen = new Array(n + 1).fill(false);
const order = [1];
seen[1] = true;
for (let i = 0; i < order.length; i++) {
  for (const to of adj[order[i]]) {
    if (!seen[to]) { seen[to] = true; parent[to] = order[i]; order.push(to); }
  }
}
const size = new Array(n + 1).fill(1), down = new Array(n + 1).fill(0);
for (let i = n - 1; i >= 0; i--) {
  const v = order[i], p = parent[v];
  if (p) { size[p] += size[v]; down[p] += down[v] + size[v]; }
}
const ans = new Array(n + 1).fill(0);
ans[1] = down[1];
for (let i = 1; i < n; i++) {
  const v = order[i];
  ans[v] = ans[parent[v]] - size[v] + (n - size[v]);
}
console.log(ans.slice(1).join("\n"));

