import java.io.*;
import java.util.*;

public class Main {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(v);
            adj[v].add(u);
        }
        int[] parent = new int[n + 1], order = new int[n];
        boolean[] seen = new boolean[n + 1];
        int head = 0, tail = 0;
        order[tail++] = 1;
        seen[1] = true;
        while (head < tail) {
            int v = order[head++];
            for (int to : adj[v]) if (!seen[to]) { seen[to] = true; parent[to] = v; order[tail++] = to; }
        }
        long[] size = new long[n + 1], down = new long[n + 1], ans = new long[n + 1];
        Arrays.fill(size, 1);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i], p = parent[v];
            if (p != 0) { size[p] += size[v]; down[p] += down[v] + size[v]; }
        }
        ans[1] = down[1];
        for (int i = 1; i < n; i++) {
            int v = order[i];
            ans[v] = ans[parent[v]] - size[v] + (n - size[v]);
        }
        StringBuilder out = new StringBuilder();
        for (int v = 1; v <= n; v++) out.append(ans[v]).append('\n');
        System.out.print(out);
    }
}

