#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> parent(n + 1, 0), order = {1};
    vector<bool> seen(n + 1, false);
    seen[1] = true;
    for (size_t i = 0; i < order.size(); i++)
        for (int to : adj[order[i]])
            if (!seen[to]) { seen[to] = true; parent[to] = order[i]; order.push_back(to); }
    vector<long long> size(n + 1, 1), down(n + 1, 0), ans(n + 1, 0);
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i], p = parent[v];
        if (p) { size[p] += size[v]; down[p] += down[v] + size[v]; }
    }
    ans[1] = down[1];
    for (int i = 1; i < n; i++) {
        int v = order[i];
        ans[v] = ans[parent[v]] - size[v] + (n - size[v]);
    }
    for (int v = 1; v <= n; v++) printf("%lld\n", ans[v]);
    return 0;
}
